'use strict';
/* محاكي مبسّط لحزمة mongodb للاختبار فقط (يخزّن في ملف JSON) — يدعم ما يستخدمه server.js */
const fs = require('fs'), FILE = process.env.FAKE_MONGO_FILE;
const enc = (k, v) => Buffer.isBuffer(v) ? { __b: v.toString('base64') } : (v && v.type === 'Buffer' && Array.isArray(v.data) ? { __b: Buffer.from(v.data).toString('base64') } : v);
const dec = (k, v) => v && v.__b !== undefined ? Buffer.from(v.__b, 'base64') : v;
let data = {}; try { data = JSON.parse(fs.readFileSync(FILE, 'utf8'), dec); } catch (e) {}
const persist = () => fs.writeFileSync(FILE, JSON.stringify(data, enc));
const clone = o => JSON.parse(JSON.stringify(o, enc), dec);
const match = (d, f) => Object.entries(f).every(([k, v]) => v && v.$in ? v.$in.includes(d[k]) : d[k] === v);
class Col {
  constructor(n) { this.n = n; data[n] = data[n] || {}; }
  get t() { return data[this.n]; }
  async createIndex() {}
  find(f) { const r = Object.values(this.t).filter(d => match(d, f)).map(clone); return { toArray: async () => r }; }
  async findOne(f) { const r = Object.values(this.t).find(d => match(d, f)); return r ? { ...clone(r), data: { buffer: r.data } } : null; }
  async replaceOne(f, doc, o) { const e = Object.values(this.t).find(d => match(d, f)); if (!e && !(o && o.upsert)) return; this.t[doc._id] = clone(doc); persist(); }
  async deleteOne(f) { for (const [k, d] of Object.entries(this.t)) if (match(d, f)) { delete this.t[k]; break; } persist(); }
  async deleteMany(f) { for (const [k, d] of Object.entries(this.t)) if (match(d, f)) delete this.t[k]; persist(); }
  async bulkWrite(ops) { for (const op of ops) { if (op.replaceOne) await this.replaceOne(op.replaceOne.filter, op.replaceOne.replacement, op.replaceOne); else if (op.deleteOne) await this.deleteOne(op.deleteOne.filter); } }
}
class MongoClient { constructor() {} async connect() {} db() { return { collection: n => new Col(n) }; } async close() {} }
module.exports = { MongoClient };
